export function getSeedsByCuisine(cuisine) {
  return RECIPE_SEEDS.filter(s => s.cuisine === cuisine);
}

export function getRandomSeeds(cuisine, count = 5) {
  const seeds = getSeedsByCuisine(cuisine);
  const shuffled = [...seeds].sort(() => 0.5 - Math.random());
  return shuffled.slice(0, count);
}

export function findSeedByName(name) {
  return RECIPE_SEEDS.find(s => s.name.toLowerCase() === name.toLowerCase());
}
